use std::collections::HashMap;
use std::fs;
use std::hint::black_box;
use std::time::Instant;
use types::symbol::{SymbolTable, SymbolVisibility};
use vm::output_artifacts::build_mapfile_text;
use vm::output_model::{MapFileDirective, MapSymbolsMode};

fn table(n: usize) -> SymbolTable {
    let mut table = SymbolTable::new();
    let odd = if n == 36 { 35 } else { 4051 };
    for i in 0..n {
        let value = (i * odd) % n;
        let name = if value % 2 == 0 {
            format!("Main.MiXeD_{value:05}")
        } else {
            format!("mAIN.mIxEd_{value:05}")
        };
        let visibility = if value % 4 == 0 { SymbolVisibility::Public } else { SymbolVisibility::Private };
        assert!(matches!(table.add(&name, value as u32, false, visibility, Some("main")), types::symbol::SymbolTableResult::Ok));
    }
    table
}

fn main() {
    let outdir = std::env::args().nth(1).expect("output directory");
    for &n in &[36usize, 4096] {
        for &(label, mode) in &[("all", MapSymbolsMode::All), ("public", MapSymbolsMode::Public)] {
            let symbols = table(n);
            let directive = MapFileDirective { path: "unused.map".into(), symbols: mode };
            let regions = HashMap::new();
            let sections = HashMap::new();
            let build = || build_mapfile_text(&directive, &regions, &sections, &symbols);
            let artifact = build();
            fs::write(format!("{outdir}/map-{n}-{label}.txt"), artifact.as_bytes()).unwrap();
            black_box(build());
            let mut samples = Vec::new();
            for _ in 0..5 {
                let started = Instant::now();
                for _ in 0..10 { black_box(build()); }
                samples.push(started.elapsed().as_nanos());
            }
            samples.sort_unstable();
            let min = samples[0];
            let max = samples[4];
            let median = samples[2];
            println!("n={n} mode={label} bytes={} samples_ns={samples:?} median_ns={median} range_ns={} range_pct_of_median={:.3}", artifact.len(), max-min, (max-min) as f64 * 100.0 / median as f64);
        }
    }
}

