use std::alloc::{GlobalAlloc, Layout, System};
use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use types::symbol::{SymbolTable, SymbolVisibility};
use vm::output_artifacts::build_mapfile_text;
use vm::output_model::{MapFileDirective, MapSymbolsMode};

struct Counting;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static REALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 { ALLOCS.fetch_add(1, Ordering::Relaxed); unsafe { System.alloc(layout) } }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) { unsafe { System.dealloc(ptr, layout) } }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 { REALLOCS.fetch_add(1, Ordering::Relaxed); unsafe { System.realloc(ptr, layout, size) } }
}
#[global_allocator] static GLOBAL: Counting = Counting;

fn table(n: usize) -> SymbolTable {
    let mut table = SymbolTable::new();
    let odd = if n == 36 { 35 } else { 4051 };
    for i in 0..n {
        let value = (i * odd) % n;
        let name = if value % 2 == 0 { format!("Main.MiXeD_{value:05}") } else { format!("mAIN.mIxEd_{value:05}") };
        let visibility = if value % 4 == 0 { SymbolVisibility::Public } else { SymbolVisibility::Private };
        assert!(matches!(table.add(&name, value as u32, false, visibility, Some("main")), types::symbol::SymbolTableResult::Ok));
    }
    table
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let n: usize = args[1].parse().unwrap();
    let mode = if args[2] == "all" { MapSymbolsMode::All } else { MapSymbolsMode::Public };
    let table = table(n);
    let directive = MapFileDirective { path: "unused.map".into(), symbols: mode };
    let regions = HashMap::new(); let sections = HashMap::new();
    ALLOCS.store(0, Ordering::SeqCst); REALLOCS.store(0, Ordering::SeqCst);
    let out = build_mapfile_text(&directive, &regions, &sections, &table);
    let allocs = ALLOCS.load(Ordering::SeqCst); let reallocs = REALLOCS.load(Ordering::SeqCst);
    println!("n={n} mode={} bytes={} allocs={allocs} reallocs={reallocs} allocation_events={}", args[2], out.len(), allocs+reallocs);
}
